from math import gcd

def divisors(m: int) -> list[int]:
    return [d for d in range(1, m + 1) if m % d == 0]

def real_cyclotomic_residue_degree(p: int, f: int) -> int:
    """Residue degree of the prime p (coprime to f) in Q(zeta_f)^+.

    Uses the divisibility criterion: deg | k  iff  p^k = +-1 (mod f).
    The degree divides phi(f)/2, so the smallest qualifying divisor is it.
    """
    if gcd(p, f) != 1 or f < 3:
        raise ValueError("need f >= 3 and gcd(p, f) = 1")
    phi = sum(1 for u in range(1, f) if gcd(u, f) == 1)
    for k in divisors(phi // 2):
        if pow(p, k, f) in (1, f - 1):
            return k
    raise AssertionError("unreachable")

def crt_components_13(p: int) -> tuple[int, int, int]:
    """(T2, T3, T6) for Q(sqrt13), the cyclic cubic field, and Q(zeta_13)^+."""
    t2 = 1 if pow(p, 6, 13) == 1 else 2
    t3 = 1 if pow(p, 4, 13) == 1 else 3
    t6 = real_cyclotomic_residue_degree(p, 13)
    assert t6 == t2 * t3 and t2 == gcd(t6, 2) and t3 == gcd(t6, 3)
    return t2, t3, t6

if __name__ == "__main__":
    for p in [2, 3, 5, 17, 29, 53, 79, 103]:
        print(p, p % 13, crt_components_13(p))

from collections import Counter, defaultdict
from math import gcd, log2
from typing import Hashable, Sequence

def entropy(v: Sequence[Hashable]) -> float:
    n = len(v)
    return -sum(c / n * log2(c / n) for c in Counter(v).values())

def cond_entropy(x: Sequence[Hashable], y: Sequence[Hashable]) -> float:
    g: dict[Hashable, list[Hashable]] = defaultdict(list)
    for xi, yi in zip(x, y):
        g[yi].append(xi)
    return sum(len(l) / len(x) * entropy(l) for l in g.values())

def semiprime_channels(n: int) -> tuple[float, float]:
    """Exact (I_pair(n), I_split(n)) in the cyclic model C_n.

    Frobenius of p, q are uniform a, b in Z/n; Frobenius of N = pq is a + b.
    """
    tau = lambda a: n // gcd(a, n)
    pair, split, res = [], [], []
    for a in range(n):
        for b in range(n):
            pair.append((tau(a), tau(b)))
            split.append((a == 0) + (b == 0))
            res.append((a + b) % n)
    ip = entropy(pair) - cond_entropy(pair, res)
    is_ = entropy(split) - cond_entropy(split, res)
    return ip, is_

if __name__ == "__main__":
    ip, is_ = semiprime_channels(6)
    print(ip, log2(3) - 1 / 9)
    print(is_, log2(3) - 55 / 36 * log2(5) + 19 / 9, is_ / ip)

from math import gcd, log2

def totient(m: int) -> int:
    return sum(1 for k in range(1, m + 1) if gcd(k, m) == 1)

def prime_power_parts(n: int) -> list[tuple[int, int]]:
    out, m, p = [], n, 2
    while p * p <= m:
        if m % p == 0:
            e = 0
            while m % p == 0:
                m //= p; e += 1
            out.append((p, e))
        p += 1
    if m > 1:
        out.append((m, 1))
    return out

def rung_entropy_prime_power(p: int, e: int) -> float:
    """H(T_{p^e}) = sum_{i=0}^{e} phi(p^i)/p^e * log2(p^e / phi(p^i))."""
    q = p ** e
    return sum(totient(p ** i) / q * log2(q / totient(p ** i)) for i in range(e + 1))

def type_entropy(n: int) -> float:
    """H(T_n) via CRT additivity over the prime-power parts of n."""
    return sum(rung_entropy_prime_power(p, e) for p, e in prime_power_parts(n))

def type_entropy_direct(n: int) -> float:
    ds = [d for d in range(1, n + 1) if n % d == 0]
    return sum(totient(d) / n * log2(n / totient(d)) for d in ds)

if __name__ == "__main__":
    for n in (6, 12, 30, 360, 2310):
        print(n, type_entropy(n), type_entropy_direct(n))
    print("H(T_6) =", type_entropy(6), "= 1/3 + log2 3 =", 1 / 3 + log2(3))

