"""Entropy budget of the ladder: H(T_n) versus sum over prime-power rungs, and semiprime channels."""
from collections import Counter, defaultdict
from math import gcd, log2
import matplotlib.pyplot as plt

def H(v):
    n = len(v); return -sum(c / n * log2(c / n) for c in Counter(v).values())

def HT(n: int) -> float:
    return H([n // gcd(a, n) for a in range(n)])

def channels(n: int) -> tuple[float, float]:
    P, S, R = [], [], []
    for a in range(n):
        for b in range(n):
            P.append((n // gcd(a, n), n // gcd(b, n))); S.append((a == 0) + (b == 0)); R.append((a + b) % n)
    def cond(x):
        g = defaultdict(list)
        for xi, r in zip(x, R): g[r].append(xi)
        return sum(len(l) / len(x) * H(l) for l in g.values())
    return H(P) - cond(P), H(S) - cond(S)

def pp(n):
    out, m, p = [], n, 2
    while p * p <= m:
        if m % p == 0:
            q = 1
            while m % p == 0: m //= p; q *= p
            out.append(q)
        p += 1
    if m > 1: out.append(m)
    return out

ns = list(range(2, 31))
fig, (ax, bx) = plt.subplots(1, 2, figsize=(13, 5))
bottoms = [0.0] * len(ns)
cmap = {2: "#1f77b4", 3: "#ff7f0e", 5: "#2ca02c", 7: "#d62728", 11: "#9467bd", 13: "#8c564b"}
for i, n in enumerate(ns):
